// ============================================================
// PORTRAIT TESTER — Frontpage Side-by-Side 4-Surface & 200%
// Dark-Matte Cutout QA Inspector (Cammy vs. Ramlethal vs. Alt. Cammy)
// ============================================================

var TESTER_ALT_PORTRAITS = {
  cammy_alt: {
    full: "data:image/jpeg;base64,",
    headshot: "data:image/jpeg;base64,"
  }
};

var PortraitTester = (() => {
  const state = {
    isOpen: false,
    viewMode: "surfaces", // "surfaces" | "zoom"
    sourceMode: "headshot", // "full" | "headshot"
    hoverScrim: false,
    mirrored: false,
    zoomLevel: 2, // 1 | 2 | 3 (2 = 200%)
    matteBg: "card", // "card" (#08090e) | "black" (#020306) | "slate" (#18243c)
    panX: 50,
    panY: 36,
    activePreset: "braids"
  };

  const PRESETS = {
    crown:   { label: "Crown & Headroom", x: 50, y: 6 },
    braids:  { label: "Neck & Braids",    x: 46, y: 58 },
    ribbons: { label: "Ribbon Edges",     x: 16, y: 44 },
    skin:    { label: "Forehead & Skin",  x: 50, y: 34 },
    center:  { label: "Center Frame",     x: 50, y: 50 }
  };

  function getSubjects() {
    const cammyChar = (typeof CHARACTERS !== "undefined" && CHARACTERS.cammy) ? CHARACTERS.cammy : null;
    const ramChar = (typeof CHARACTERS !== "undefined" && CHARACTERS.ramlethal) ? CHARACTERS.ramlethal : null;
    const cammyFull = (typeof FIGHTER_PHOTOS !== "undefined" && FIGHTER_PHOTOS.cammy) || "";
    const cammyHs = (typeof FIGHTER_HEADSHOTS !== "undefined" && FIGHTER_HEADSHOTS.cammy) || cammyFull;
    const ramFull = (typeof FIGHTER_PHOTOS !== "undefined" && FIGHTER_PHOTOS.ramlethal) || "";
    const ramHs = (typeof FIGHTER_HEADSHOTS !== "undefined" && FIGHTER_HEADSHOTS.ramlethal) || ramFull;
    const altFull = (TESTER_ALT_PORTRAITS && TESTER_ALT_PORTRAITS.cammy_alt && TESTER_ALT_PORTRAITS.cammy_alt.full) || "";
    const altHs = (TESTER_ALT_PORTRAITS && TESTER_ALT_PORTRAITS.cammy_alt && TESTER_ALT_PORTRAITS.cammy_alt.headshot) || altFull;

    return [
      {
        id: "cammy",
        name: "Cammy",
        kicker: "Live Benchmark · Original Source",
        meta: "480×714 Full · 480×600 HS · Default Auto-Matte",
        note: "Baseline proportion & lighting benchmark. Exhibits trapped #FFFFFF islands between left hair wisps/flames and right braid/neck, 0px beret headroom, and Voronoi forehead crackle.",
        cardTitle: cammyChar ? cammyChar.name : "Cammy",
        cardBlurb: cammyChar && cammyChar.blurb ? cammyChar.blurb : "Agile close-range striker who Crosses through the opponent to guarantee range.",
        fullSrc: cammyFull,
        headshotSrc: cammyHs
      },
      {
        id: "ramlethal",
        name: "Ramlethal Valentine",
        kicker: "Live Roster · Creation Guide Redraw",
        meta: "480×714 Full · 480×600 HS · Ink-Sealed Cloak",
        note: "Weapon/Prop-Heavy archetype redrawn via Creation Guide. Warm-ivory shaded cap & cloak sealed in dark ink with crimson/emerald energy strictly behind the silhouette.",
        cardTitle: ramChar ? ramChar.name : "Ramlethal",
        cardBlurb: ramChar && ramChar.blurb ? ramChar.blurb : "Mid-range greatsword zoner who pays Force at set time to extend attack reach.",
        fullSrc: ramFull,
        headshotSrc: ramHs
      },
      {
        id: "cammy_alt",
        name: "Alt. Cammy",
        kicker: "Tester Only · Creation Guide + Reference",
        meta: "480×715 Full · 480×600 HS · Zero Cutout Islands",
        note: "Generated from the updated Creation Guide + Cammy style reference override: 3% top beret headroom, cohesive pocket-free hair & braids, smooth painterly skin, and behind-only ribbons.",
        cardTitle: "Cammy (Alt)",
        cardBlurb: cammyChar && cammyChar.blurb ? cammyChar.blurb : "Agile close-range striker who Crosses through the opponent to guarantee range.",
        fullSrc: altFull,
        headshotSrc: altHs
      }
    ];
  }

  function escHtml(str) {
    if (typeof esc === "function") return esc(str);
    return String(str == null ? "" : str)
      .replace(/&/g, "&amp;")
      .replace(/</g, "&lt;")
      .replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;");
  }

  function matteClass() {
    if (state.matteBg === "black") return "pt-matte-black";
    if (state.matteBg === "slate") return "pt-matte-slate";
    return "pt-matte-card";
  }

  function renderSurfacesColumn(subj) {
    const cardSrc = state.sourceMode === "headshot" ? subj.headshotSrc : subj.fullSrc;
    const hsSrc = subj.headshotSrc || subj.fullSrc;
    const hudSrc = subj.headshotSrc || subj.fullSrc;
    const plaqueSrc = state.sourceMode === "headshot" ? subj.headshotSrc : subj.fullSrc;
    const mCls = matteClass();

    return `
      <section class="pt-col" aria-label="${escHtml(subj.name)} comparison column">
        <header class="pt-col-head">
          <div class="pt-col-kicker">${escHtml(subj.kicker)}</div>
          <h3 class="pt-col-title">${escHtml(subj.name)}</h3>
          <div class="pt-col-meta">${escHtml(subj.meta)}</div>
          <p class="pt-col-note">${escHtml(subj.note)}</p>
        </header>

        <div class="pt-surfaces-top">
          <div class="pt-surface-block">
            <div class="pt-surface-hdr">
              <span class="pt-surface-name">01. Select Card</span>
              <span class="pt-surface-spec">3:4 · ${state.sourceMode === "headshot" ? "HS" : "Full"}</span>
            </div>
            <div class="pt-card-stage ${mCls}">
              <div class="fighter-card pt-preview-card${state.hoverScrim ? " pt-force-hover" : ""}" onclick="PortraitTester.inspectInZoom('braids')" title="Click to inspect in 200% Cutout Zoom">
                <div class="fighter-card-bg">
                  <img class="fighter-photo" src="${cardSrc}" alt="${escHtml(subj.name)} Fighter Select card" referrerpolicy="no-referrer"/>
                </div>
                <div class="fighter-card-scrim"></div>
                <div class="fighter-card-text">
                  <h2 class="fighter-card-name" style="color:#f87171;">${escHtml(subj.cardTitle)}</h2>
                  <p class="fighter-card-blurb">${escHtml(subj.cardBlurb)}</p>
                </div>
              </div>
            </div>
          </div>

          <div class="pt-surface-block">
            <div class="pt-surface-hdr">
              <span class="pt-surface-name">02. Headshot</span>
              <span class="pt-surface-spec">4:5 · 480×600</span>
            </div>
            <button type="button" class="pt-hs-stage ${mCls}" onclick="PortraitTester.inspectInZoom('braids')" aria-label="Inspect ${escHtml(subj.name)} Headshot at 200% zoom">
              <img class="pt-hs-img" src="${hsSrc}" alt="${escHtml(subj.name)} 4:5 Headshot" referrerpolicy="no-referrer"/>
              <span class="pt-hs-cta">200% Zoom</span>
            </button>
          </div>
        </div>

        <div class="pt-surface-pair">
          <div class="pt-surface-block">
            <div class="pt-surface-hdr">
              <span class="pt-surface-name">03. Match HUD Avatars</span>
              <span class="pt-surface-spec">1:1 · 36px &amp; 24px</span>
            </div>
            <div class="pt-hud-stage">
              <div class="pt-hud-strip you-strip">
                <img class="pt-hud-avatar sz-36" src="${hudSrc}" alt="${escHtml(subj.name)} 36px HUD avatar" referrerpolicy="no-referrer"/>
                <div class="pt-hud-info">
                  <div class="pt-hud-line"><span class="pt-hud-tag">You · 36px</span><span class="pt-hud-hp">30 HP</span></div>
                  <div class="pt-hud-bar"><i style="width:86%"></i></div>
                </div>
              </div>
              <div class="pt-hud-strip cpu-strip">
                <img class="pt-hud-avatar sz-24" src="${hudSrc}" alt="${escHtml(subj.name)} 24px compact HUD avatar" referrerpolicy="no-referrer"/>
                <div class="pt-hud-info">
                  <div class="pt-hud-line"><span class="pt-hud-tag">Compact · 24px</span><span class="pt-hud-hp">24 HP</span></div>
                  <div class="pt-hud-bar cpu"><i style="width:72%"></i></div>
                </div>
              </div>
            </div>
          </div>

          <div class="pt-surface-block">
            <div class="pt-surface-hdr">
              <span class="pt-surface-name">04. Arena Plaque</span>
              <span class="pt-surface-spec">5:6 · ${state.mirrored ? "Mirrored (-1)" : "Normal (+1)"}</span>
            </div>
            <div class="pt-plaque-stage ${mCls}">
              <div class="pt-plaque-pair">
                <div class="pt-plaque-token you-plaque${state.mirrored ? " is-mirrored" : ""}">
                  <div class="pt-plaque-inner">
                    <img src="${plaqueSrc}" alt="${escHtml(subj.name)} Arena plaque" referrerpolicy="no-referrer"/>
                  </div>
                  <span class="pt-plaque-dir">${state.mirrored ? "← P2 Flip" : "P1 →"}</span>
                </div>
                <div class="pt-plaque-token cpu-plaque${!state.mirrored ? " is-mirrored" : ""}">
                  <div class="pt-plaque-inner">
                    <img src="${plaqueSrc}" alt="${escHtml(subj.name)} Mirrored Arena plaque" referrerpolicy="no-referrer"/>
                  </div>
                  <span class="pt-plaque-dir">${!state.mirrored ? "← Mirror" : "Normal →"}</span>
                </div>
              </div>
            </div>
          </div>
        </div>
      </section>
    `;
  }

  function renderZoomColumn(subj) {
    const src = state.sourceMode === "headshot" ? (subj.headshotSrc || subj.fullSrc) : subj.fullSrc;
    const mCls = matteClass();
    const scale = state.zoomLevel;
    const ox = state.panX.toFixed(1);
    const oy = state.panY.toFixed(1);

    return `
      <section class="pt-col pt-zoom-col" aria-label="${escHtml(subj.name)} zoom column">
        <header class="pt-col-head">
          <div class="pt-col-kicker">${escHtml(subj.kicker)}</div>
          <h3 class="pt-col-title">${escHtml(subj.name)}</h3>
          <div class="pt-col-meta">${escHtml(subj.meta)}</div>
          <p class="pt-col-note">${escHtml(subj.note)}</p>
        </header>
        <div class="pt-zoom-viewport ${mCls}" data-pt-loupe="true">
          <img
            class="pt-zoom-img"
            src="${src}"
            alt="${escHtml(subj.name)} magnified cutout view"
            referrerpolicy="no-referrer"
            draggable="false"
            style="transform: scale(${scale}); transform-origin: ${ox}% ${oy}%;"
          />
          <div class="pt-zoom-crosshair" style="left:${ox}%;top:${oy}%;" aria-hidden="true"></div>
          <div class="pt-zoom-hud">
            <span>${Math.round(scale * 100)}% · ${state.sourceMode === "headshot" ? "4:5 Headshot" : "3:4 Full"}</span>
            <span>Focal: ${Math.round(state.panX)}% X, ${Math.round(state.panY)}% Y</span>
          </div>
        </div>
      </section>
    `;
  }

  function buildHTML() {
    const subjects = getSubjects();
    const colsHTML = subjects
      .map(s => state.viewMode === "zoom" ? renderZoomColumn(s) : renderSurfacesColumn(s))
      .join("");

    const presetBtns = Object.keys(PRESETS).map(k => {
      const p = PRESETS[k];
      const active = state.activePreset === k ? " active" : "";
      return `<button type="button" class="pt-seg-btn${active}" onclick="PortraitTester.applyPreset('${k}')">${escHtml(p.label)}</button>`;
    }).join("");

    return `
      <div class="pt-modal" role="dialog" aria-modal="true" aria-labelledby="ptModalTitle">
        <header class="pt-header">
          <div class="pt-title-group">
            <h2 class="pt-title" id="ptModalTitle">Portrait Creation Guide &amp; Cutout Tester</h2>
            <span class="pt-subtitle">Cammy Benchmark vs. Ramlethal Guide Redraw vs. Alt. Cammy (Creation Guide + Style Reference)</span>
          </div>
          <button type="button" class="pt-close-btn" onclick="closePortraitTester()" aria-label="Close Portrait Tester">✕ Close</button>
        </header>

        <div class="pt-toolbar">
          <div class="pt-tool-group">
            <span class="pt-tool-label">View</span>
            <div class="pt-seg">
              <button type="button" class="pt-seg-btn${state.viewMode === "surfaces" ? " active" : ""}" onclick="PortraitTester.setViewMode('surfaces')">All 4 UI Surfaces</button>
              <button type="button" class="pt-seg-btn${state.viewMode === "zoom" ? " active" : ""}" onclick="PortraitTester.setViewMode('zoom')">200% Cutout Zoom</button>
            </div>
          </div>

          <div class="pt-tool-group">
            <span class="pt-tool-label">Source</span>
            <div class="pt-seg">
              <button type="button" class="pt-seg-btn${state.sourceMode === "full" ? " active" : ""}" onclick="PortraitTester.setSourceMode('full')">Full (3:4)</button>
              <button type="button" class="pt-seg-btn${state.sourceMode === "headshot" ? " active" : ""}" onclick="PortraitTester.setSourceMode('headshot')">Headshot (4:5)</button>
            </div>
          </div>

          <div class="pt-tool-group">
            <span class="pt-tool-label">Matte</span>
            <div class="pt-seg">
              <button type="button" class="pt-seg-btn${state.matteBg === "card" ? " active" : ""}" onclick="PortraitTester.setMatteBg('card')">Card Dark (#08090e)</button>
              <button type="button" class="pt-seg-btn${state.matteBg === "black" ? " active" : ""}" onclick="PortraitTester.setMatteBg('black')">Pitch Black</button>
              <button type="button" class="pt-seg-btn${state.matteBg === "slate" ? " active" : ""}" onclick="PortraitTester.setMatteBg('slate')">Slate Contrast</button>
            </div>
          </div>

          ${state.viewMode === "surfaces" ? `
            <div class="pt-tool-group">
              <span class="pt-tool-label">Surface Checks</span>
              <div class="pt-seg">
                <button type="button" class="pt-seg-btn${state.hoverScrim ? " active" : ""}" onclick="PortraitTester.toggleHoverScrim()">Hover Scrim (38%)</button>
                <button type="button" class="pt-seg-btn${state.mirrored ? " active" : ""}" onclick="PortraitTester.toggleMirrored()">Mirror Plaque (-1)</button>
              </div>
            </div>
          ` : `
            <div class="pt-tool-group">
              <span class="pt-tool-label">Magnification</span>
              <div class="pt-seg">
                <button type="button" class="pt-seg-btn${state.zoomLevel === 1.5 ? " active" : ""}" onclick="PortraitTester.setZoomLevel(1.5)">150%</button>
                <button type="button" class="pt-seg-btn${state.zoomLevel === 2 ? " active" : ""}" onclick="PortraitTester.setZoomLevel(2)">200%</button>
                <button type="button" class="pt-seg-btn${state.zoomLevel === 3 ? " active" : ""}" onclick="PortraitTester.setZoomLevel(3)">300%</button>
              </div>
            </div>
            <div class="pt-tool-group">
              <span class="pt-tool-label">Focus Zone (Drag Any Pane to Pan All 3)</span>
              <div class="pt-seg">
                ${presetBtns}
              </div>
            </div>
          `}
        </div>

        <div class="pt-grid">
          ${colsHTML}
        </div>
      </div>
    `;
  }

  function applyZoomTransformInPlace() {
    if (typeof document === "undefined") return;
    const scale = state.zoomLevel;
    const ox = state.panX.toFixed(1);
    const oy = state.panY.toFixed(1);
    document.querySelectorAll(".pt-zoom-img").forEach(img => {
      img.style.transform = `scale(${scale})`;
      img.style.transformOrigin = `${ox}% ${oy}%`;
    });
    document.querySelectorAll(".pt-zoom-crosshair").forEach(ch => {
      ch.style.left = `${ox}%`;
      ch.style.top = `${oy}%`;
    });
    document.querySelectorAll(".pt-zoom-hud").forEach(hud => {
      hud.innerHTML = `<span>${Math.round(scale * 100)}% · ${state.sourceMode === "headshot" ? "4:5 Headshot" : "3:4 Full"}</span><span>Focal: ${Math.round(state.panX)}% X, ${Math.round(state.panY)}% Y</span>`;
    });
  }

  function bindZoomDrag() {
    if (typeof document === "undefined") return;
    const loupes = document.querySelectorAll("[data-pt-loupe]");
    loupes.forEach(loupe => {
      let dragging = false;
      const updateFromEvent = (ev) => {
        const rect = loupe.getBoundingClientRect();
        if (!rect.width || !rect.height) return;
        const clientX = ev.touches && ev.touches[0] ? ev.touches[0].clientX : ev.clientX;
        const clientY = ev.touches && ev.touches[0] ? ev.touches[0].clientY : ev.clientY;
        const nx = Math.max(0, Math.min(100, ((clientX - rect.left) / rect.width) * 100));
        const ny = Math.max(0, Math.min(100, ((clientY - rect.top) / rect.height) * 100));
        state.panX = nx;
        state.panY = ny;
        state.activePreset = null;
        applyZoomTransformInPlace();
      };
      loupe.addEventListener("pointerdown", (ev) => {
        dragging = true;
        if (loupe.setPointerCapture && ev.pointerId != null) {
          try { loupe.setPointerCapture(ev.pointerId); } catch (_) {}
        }
        updateFromEvent(ev);
      });
      loupe.addEventListener("pointermove", (ev) => {
        if (!dragging) return;
        updateFromEvent(ev);
      });
      const stop = () => { dragging = false; };
      loupe.addEventListener("pointerup", stop);
      loupe.addEventListener("pointercancel", stop);
    });
  }

  function renderModal() {
    if (typeof document === "undefined") return;
    const overlay = document.getElementById("portraitTesterOverlay");
    if (!overlay) return;
    if (!state.isOpen) {
      overlay.style.display = "none";
      overlay.setAttribute("aria-hidden", "true");
      overlay.innerHTML = "";
      return;
    }
    overlay.style.display = "flex";
    overlay.setAttribute("aria-hidden", "false");
    overlay.innerHTML = buildHTML();
    if (state.viewMode === "zoom") {
      bindZoomDrag();
    }
  }

  function open(opts) {
    if (opts && opts.viewMode) state.viewMode = opts.viewMode;
    else state.viewMode = "surfaces";
    if (opts && opts.sourceMode) state.sourceMode = opts.sourceMode;
    state.isOpen = true;
    renderModal();
  }

  function close() {
    if (!state.isOpen) return;
    state.isOpen = false;
    renderModal();
  }

  function setViewMode(mode) {
    state.viewMode = mode === "zoom" ? "zoom" : "surfaces";
    if (state.viewMode === "zoom" && !state.activePreset) {
      state.activePreset = "braids";
    }
    renderModal();
  }

  function setSourceMode(mode) {
    state.sourceMode = mode === "full" ? "full" : "headshot";
    renderModal();
  }

  function setMatteBg(bg) {
    state.matteBg = (bg === "black" || bg === "slate") ? bg : "card";
    renderModal();
  }

  function setZoomLevel(lvl) {
    state.zoomLevel = Number(lvl) || 2;
    renderModal();
  }

  function toggleHoverScrim() {
    state.hoverScrim = !state.hoverScrim;
    renderModal();
  }

  function toggleMirrored() {
    state.mirrored = !state.mirrored;
    renderModal();
  }

  function applyPreset(key) {
    const p = PRESETS[key];
    if (!p) return;
    state.activePreset = key;
    state.panX = p.x;
    state.panY = p.y;
    state.viewMode = "zoom";
    renderModal();
  }

  function inspectInZoom(presetKey, sourceOverride) {
    const p = PRESETS[presetKey || "braids"] || PRESETS.braids;
    state.activePreset = presetKey || "braids";
    state.panX = p.x;
    state.panY = p.y;
    state.zoomLevel = 2;
    if (sourceOverride === "headshot" || sourceOverride === "full") {
      state.sourceMode = sourceOverride;
    } else {
      state.sourceMode = "headshot";
    }
    state.viewMode = "zoom";
    renderModal();
  }

  return {
    state,
    open,
    close,
    setViewMode,
    setSourceMode,
    setMatteBg,
    setZoomLevel,
    toggleHoverScrim,
    toggleMirrored,
    applyPreset,
    inspectInZoom,
    isOpen: () => state.isOpen
  };
})();

function openPortraitTester(opts) {
  return PortraitTester.open(opts);
}

function closePortraitTester() {
  return PortraitTester.close();
}
